import smtplib
from email.mime.text import MIMEText
from typing import Optional

def send_phishing_email(email_to: str, email_from: str, subject: str, body: str, server: str, port: int, password: Optional[str] = None):
    server = smtplib.SMTP(host=server, port=port)
    server.login(email_from, password)
    message = MIMEText(body, 'plain', 'utf-8')
    message.add_header('From', f"{email_from}")
    message.add_header('To', email_to)
    message.add_header('Subject', subject)
    server.sendmail(email_from, email_to, message)
    server.quit()

