    msg['To'] = test_email
    msg['Subject'] = 'Account Verification Required'
    server.sendmail(test_email, msg.as_string())
    server.quit()
    return "Thank you for verifying your account."

if __name__ == '__main__':
    app.run(debug=True, port=5000)
```

