               margin: 10px 0;
               padding: 8px;
               width: 80%;
               max-width: 300px;
           }
           .submit-btn {
               background-color: #007bff;
               color: white;
               padding: 10px 20px;
               border: none;
               border-radius: 4px;
               cursor: pointer;
           }
           .submit-btn:hover {
               background-color: #0056b3;
           }
           .terms {
               font-size: 6px;
               color: #666;
           }
       </style>
