       server = smtplib.SMTP('smtp.gmail.com', 587)
       server.login('phishing@test.com', 'your_app_specific_password')
       server.sendmail(to, to, message)
       server.close()
       return "Email sent successfully!"

   app.run(host='0.0.0.0', port=5000)
