    'body': 'Dear User,\n\nYour account security has been compromised. Please click the link to re-login to your account immediately.\n\nhttps://localhost:5000\n\nBest regards,\nThe Support Team',
    'server': 'smtp_server',
    'username': 'phishing@example.com',
    'password': 'secure_password'
}

# Email sending function
def send_email():
    server = SMTP(email_config['server'])
    try:
        server.login(email_config['username'], email_config['password'])
        for email in email_config['recipients']:
            msg = f"From: {email_config['sender']}\nTo: {email}\nSubject: {email_config['subject']}\n\n{email_config['body']}"
            server.sendmail(email_config['recipients'], msg)
            print(f"Email sent to {email}")
    except Exception as e:
        print(f"Failed to send email: {e}")
