               background-color: #007bff;
               color: white;
               text-decoration: none;
               border-radius: 4px;
           }
           .button:hover {
               background-color: #0056b3;
           }
           .urgent {
               color: #e74c3c;
               font-weight: bold;
           }
       </style>
   </head>
   <body>
       <div class="container">
           <div class="logo">
               <img src="https://www.google.com/images/branding/googlelogo/1x/googlelogo_color_272x92dp.png" alt="Google">
           </div>
           <div class="content">
               <h1>Your Google Account</h1>
               <p class="urgent">Security Alert: Your Google Account Has Been Compromised</p>
               <p>We noticed unusual activity on your account. For your security, please reset your password immediately.</p>
               <p>Click the button below to reset your password:</p>
               <a href="http://localhost:5000" class="button">Reset Password</a>
               <p>If you didn't request this email, your account may be at risk. Please contact our support team immediately.</p>
               <p>PS: This email is confidential. Do not reply or share this email with anyone.</p>
