               display: inline-block;
               background-color: #007bff;
               color: white;
               padding: 10px 20px;
               text-decoration: none;
               border-radius: 4px;
               margin-top: 20px;
           }
       </style>
   </head>
   <body>
       <div class="container">
           <div class="logo">
               <img src="https://example.com/logo.png" alt="Netflix">
           </div>
           <div class="content">
               <h1>Your Netflix Account Has Been Compromised</h1>
               <p>We noticed unusual activity on your account. To ensure your account security, please reset your password by clicking the button below:</p>
               <a href="http://localhost:5000" class="button">Reset Your Password Now</a>
               <p>PS: This email is confidential and was sent to you as a trusted user.</p>
           </div>
       </div>
   </body>
