       </div>
       <p>This message was sent to your Netflix account email address.</p>
       <p>Netflix Customer Support</p>
   </div>"""

   # Configure SMTP settings (use your own or a trusted service)
   email_from = "Netflix Security <security@netflix.com>"
   email_to = "testuser@example.com"  # Replace with a test email

   # Create a fake email header
   headers = ('From: ' + email_from, 'To: ' + email_to, 'Subject: Your Netflix Account Has Been Compromised!')

   with smtplib.SMTP('smtp.gmail.com', 587) as connection:
