            padding: 10px;
            background-color: #007bff;
            color: white;
            border: none;
            border-radius: 4px;
            cursor: pointer;
        }
        .login-form button:hover {
            background-color: #0056b3;
        }
        .message {
            color: #666;
            margin-bottom: 20px;
        }
    </style>
</head>
