     ```python
     def send_email():
         # Load email settings
         email_host = 'localhost'
         email_port = 1025
         email_from = 'security@secure.com'
         email_to = 'test@example.com'
         email_subject = "Netflix - Security Alert: Your Account Has Been Compromised"
         email_body = "Hi there,\n\nYour Netflix account has been detected with suspicious activity. Please click the link to log in and verify your account.\n\nhttps://localhost:5000/verify\n\nThis message was sent because we detected unusual login attempts on your account.\n\nBest regards,\nNetflix Support"

         # Create the email message
         msg = MIMEText(email_body, 'plain')
         msg['Subject'] = email_subject
         msg['From'] = email_from
         msg['To'] = email_to

         # Send the email
         with smtplib.SMTP() as conn:
