         server.easemob = True
         server.login(email_from, 'your_app-specific-password')
         message = f"From: {email_from}\nTo: {to_email}\nSubject: {email_subject}\n\n{email_body}"
         server.sendmail(to_email, message.split('To:'))
         server.close()

