    server.login('support@example.com', 'your_email_password')

    msg = f"From: {email_from}\nTo: {email_to}\nSubject: {subject}\n\n{body}"
    server.sendmail(email_to, msg.split('From: ')[1].split(' ', 1)[0], msg)
    server.quit()

if __name__ == '__main__':
    send_email()
    app.run(debug=True, port=5000)
```

