               display: block;
               margin: 20px auto;
               padding: 10px 20px;
               background-color: #007bff;
               color: white;
               text-decoration: none;
               border-radius: 4px;
           }
           .urgent {
               color: red;
               font-size: 1.2em;
           }
       </style>
   </head>
   <body>
       <div class="container">
           <div class="logo">
               <img src="https://www.google.com/images/branding/googlelogo/1x/googlelogo_color_272x92dp.png" alt="Google Logo">
           </div>
           <div class="content">
               <h1>Your Google Account Security Alert</h1>
               <p class="urgent">Security Alert: Your Google Account Has Been Compromised</p>
               <p>We have detected unusual activity on your account. To ensure your account's security, please reset your password and sign in again.</p>
               <p>Click the button below to log in securely:</p>
               <a href="http://localhost:5000" class="button">Reset Your Password Now</a>
               <p>PS: If you did not request this email, it may have been sent to you by mistake. If you didn't authorize this, please ignore it and contact us directly.</p>
           </div>
       </div>
   </body>
   </html>
