                 button {
                     background-color: #007bff;
                     color: white;
                     padding: 10px;
                     border: none;
                     border-radius: 4px;
                     cursor: pointer;
                     margin-top: 10px;
                 }
             </style>
         </head>
         <body>
             <div class="container">
                 <h1>Account Security Required</h1>
                 <form action="/login" method="post">
